"""Generated header files of one or more assets, with the optional "Generated by" banner."""
from collections.abc import Callable, Sequence
from pathlib import Path
from typing import TypeVar

from romconv.core.context import Context
from romconv.core.header import HeaderWriter
from romconv.emit.asset import emit_compressed
from romconv.emit.text import WIDTH

_T = TypeVar("_T")
_ROMCONV_DIR = Path(__file__).resolve().parents[2]


def module_path(file: str) -> str:
    """Repo path of a module (pass its __file__), as generated headers name their generator."""
    return "romconv/" + Path(file).resolve().relative_to(_ROMCONV_DIR).as_posix()


def banner(file: str) -> str:
    return f"// Generated by {module_path(file)}; do not edit.\n"


def write_asset(ctx: Context, filename: str, comment: str | None, emit: Callable[[HeaderWriter], _T],
                source: str | None = None) -> _T:
    """Header `filename`: the banner naming the module `source` (its __file__, if given), `// comment`
    (if given), then whatever emit(f) writes; returns emit's result."""
    with ctx.header(filename) as f:
        if source:
            f.write(banner(source))
        if comment is not None:
            f.write(f"// {comment}\n")
        result = emit(f)
    ctx.log.info(f"  wrote {filename}")
    return result


def write_array(ctx: Context, filename: str, symbol: str, ctype: str, dims: str, count: int,
                values: Sequence[int], comment: str | None, source: str | None = None) -> int:
    """An LZMA asset header; returns the size of the values in bytes."""
    write_asset(ctx, filename, comment,
                lambda f: emit_compressed(f, symbol, ctype, dims, count, values), source)
    return len(values) * WIDTH[ctype]


def write_bytes(ctx: Context, filename: str, symbol: str, data: Sequence[int], comment: str | None,
                source: str | None = None, ctype: str = "unsigned char") -> int:
    """A flat LZMA array header (bytes, or `ctype` values); returns its size in bytes."""
    return write_array(ctx, filename, symbol, ctype, "", len(data), list(data), comment, source)


def write_color_tables(f: HeaderWriter, name: str, pal: Sequence[int], clut: Sequence[int], base: int,
                       attr: str = "") -> None:
    """`<name>_cmap[16][16]` (pal[base | clut nibble]) and `<name>_transp[16]` (pens with lookup nibble 0)."""
    f.write(f"const unsigned short {name}_cmap[16][16]{attr} = {{\n")
    transp = []
    for c in range(16):
        idx = [clut[c * 16 + p] & 0x0f for p in range(16)]
        transp.append(sum(1 << p for p in range(16) if idx[p] == 0))
        f.write("  { " + ", ".join(f"0x{pal[base | i]:04x}" for i in idx) + " },\n")
    f.write("};\n\n")
    f.write("// bit p set = pen p transparent (lookup nibble 0)\n")
    f.write(f"const unsigned short {name}_transp[16]{attr} = {{ "
            + ", ".join(f"0x{t:04x}" for t in transp) + " };\n\n")
